"""Presentación final concisa; cifras derivadas de evidencia identificada."""
from pathlib import Path
import html,json
R=Path(__file__).resolve().parents[1]
def read(p):return json.loads(p.read_text(encoding='utf-8'))
def link(url,label):return f'<a class="link" target="_blank" href="{html.escape(url,quote=True)}">{html.escape(label)}</a>'
def paragraph(s):return '<p>'+s+'</p>'
def cards(items):return '<div class="cards">'+''.join('<article><div class="number">'+str(a)+'</div><h2>'+b+'</h2><p>'+c+'</p></article>'for a,b,c in items)+'</div>'
def table(headers,rows):return '<div class="scroll"><table><thead><tr>'+''.join('<th>'+h+'</th>'for h in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+str(x)+'</td>'for x in row)+'</tr>'for row in rows)+'</tbody></table></div>'
def command(s):return '<div class="cmd"><button class="copy">Copiar</button><pre><code>'+html.escape(s)+'</code></pre></div>'
